function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
}

function topics() {
  return Object.keys(BANK);
}

function pickSet(topic) {
  const t = String(topic || '').toLowerCase().trim();
  if (!t) return BANK.general;
  if (BANK[t]) return BANK[t];
  let best = null;
  let bestScore = 0;
  Object.keys(BANK).forEach(name => {
    const set = BANK[name];
    let score = 0;
    set.keys.concat([name]).forEach(k => {
      if (t.includes(k) || k.includes(t)) score = Math.max(score, k.length);
    });
    if (score > bestScore) { bestScore = score; best = set; }
  });
  return best;
}

/* returns [{ text, answers[4], correct, time }] with the correct answer
   shuffled into a random slot each time */
function generate(topic, count) {
  const set = pickSet(topic);
  if (!set) return [];
  return shuffle(set.q).slice(0, count).map(row => {
    const text = row[0];
    const right = row[1];
    const options = shuffle([row[1], row[2], row[3], row[4]]);
    return {
      text,
      answers: options,
      correct: options.indexOf(right),
      time: 20,
      image: row[5] || ''
    };
  });
}

const quizCodes = new Map();
function normalizeCode(code) {
  if (typeof code !== 'string') return '';
  return code.trim().toUpperCase().replace(/[^A-Z0-9-]/g, '').slice(0, 14);
}
function randCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let s = '';
  for (let i = 0; i < 5; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return 'MOKI-' + s;
}
const store = {
  init: () => Promise.resolve('in-memory (single-file mode - codes reset on restart)'),
  put: async quiz => {
    let code, guard = 0;
    do { code = randCode(); } while (quizCodes.has(code) && ++guard < 100);
    quizCodes.set(code, quiz);
    return code;
  },
  get: async code => quizCodes.get(normalizeCode(code)) || null
};

/* Tiny in-memory rate limiter. No dependency, no store - this server already
   keeps all its game state in memory, so a per-process limiter is consistent
   with the rest of it (and MOKI runs as a single instance by design). */

function createLimiter(opts) {
  const windowMs = opts.windowMs;
  const max = opts.max;
  const name = opts.name || 'requests';
  const hits = new Map();   // key -> { count, resetAt }

  // keep the map from growing without bound
  const sweep = setInterval(() => {
    const now = Date.now();
    hits.forEach((v, k) => { if (v.resetAt <= now) hits.delete(k); });
  }, Math.max(windowMs, 30000));
  if (sweep.unref) sweep.unref();

  return function limit(req, res, next) {
    const key = req.ip || (req.socket && req.socket.remoteAddress) || 'unknown';
    const now = Date.now();
    let entry = hits.get(key);

    if (!entry || entry.resetAt <= now) {
      entry = { count: 0, resetAt: now + windowMs };
      hits.set(key, entry);
    }
    entry.count += 1;

    const remaining = Math.max(0, max - entry.count);
    res.setHeader('X-RateLimit-Limit', String(max));
    res.setHeader('X-RateLimit-Remaining', String(remaining));

    if (entry.count > max) {
      const retry = Math.ceil((entry.resetAt - now) / 1000);
      res.setHeader('Retry-After', String(retry));
      return res.status(429).json({
        ok: false,
        error: 'Too many ' + name + ' from this device. Try again in ' + retry + 's.'
      });
    }
    next();
  };
}

/* Socket events need the same protection - a socket can spam host:create or
   player:join far faster than HTTP. This counts per socket id. */
function createSocketLimiter(opts) {
  const windowMs = opts.windowMs;
  const max = opts.max;
  const hits = new Map();

  const sweep = setInterval(() => {
    const now = Date.now();
    hits.forEach((v, k) => { if (v.resetAt <= now) hits.delete(k); });
  }, Math.max(windowMs, 30000));
  if (sweep.unref) sweep.unref();

  return {
    /* returns true when the action is allowed */
    allow(key) {
      const now = Date.now();
      let entry = hits.get(key);
      if (!entry || entry.resetAt <= now) {
        entry = { count: 0, resetAt: now + windowMs };
        hits.set(key, entry);
      }
      entry.count += 1;
      return entry.count <= max;
    },
    forget(key) { hits.delete(key); }
  };
}


/* Public endpoints are rate limited per IP - this app is on a public URL and
   the quiz library is shared, so one script should not be able to fill it. */
const sparkLimit = createLimiter({ windowMs: 60000, max: 20, name: 'question requests' });
const saveLimit  = createLimiter({ windowMs: 60000, max: 10, name: 'quiz saves' });
const readLimit  = createLimiter({ windowMs: 60000, max: 60, name: 'lookups' });

/* Socket floods: creating games and joining are the expensive ones. */
const createLimit = createSocketLimiter({ windowMs: 60000, max: 12 });
const joinLimit   = createSocketLimiter({ windowMs: 60000, max: 30 });

const app = express();
// Render sits behind a proxy, so req.ip must come from X-Forwarded-For
app.set('trust proxy', 1);
app.use(express.json({ limit: '3mb' }));
